'use strict';
const P=require('./policy.cjs'),S=require('./source-bundle.cjs'),J=require('./job.cjs');
function validate(v,a){if(!P.exact(v,['kind','approval','manifest','files','material','publicEnv','ownerId','runtimeLockSha256'])||v.kind!=='ROOT_PROTECTED_IOS16_BUILD_INPUT'||JSON.stringify(P.canonical(v.approval))!==JSON.stringify(P.canonical(a))||!P.SHA.test(v.runtimeLockSha256)||typeof v.ownerId!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(v.ownerId)||P.sha(v.ownerId)!==a.ownerAccountSha256||P.sha(Buffer.from(JSON.stringify(v.manifest,null,2)+'\n'))!==a.publicSourceManifestSha256)P.fail();S.manifest(v.manifest);J.env(v.publicEnv);if(!P.exact(v.material,['p12','cms','password'])||typeof v.material.password!=='string'||v.material.password.length>1024)P.fail();for(const k of ['p12','cms']){const s=v.material[k];if(typeof s!=='string'||s.length<4||s.length>1048576)P.fail();const b=Buffer.from(s,'base64');if(b.length<1||b.length>524288||b.toString('base64')!==s)P.fail();}return {...v,rows:S.overlay(S.verifyFiles(v.manifest,v.files))};}
function packageInput(a,manifest,files,material,publicEnv,ownerId,runtimeLockSha256){const v={kind:'ROOT_PROTECTED_IOS16_BUILD_INPUT',approval:a,manifest,files,material:{p12:material.p12.toString('base64'),cms:material.cms.toString('base64'),password:material.password},publicEnv,ownerId,runtimeLockSha256};validate(v,a);return Buffer.from(JSON.stringify(v));}
module.exports={validate,packageInput};
